// ========================================
// SIMPLE GENERATOR - FULLY GENERIC
// ========================================
// This node generates full datasets (up to 10k records) using patterns
// extracted from AI Mode preview or Schema Builder manual input.

// n8n Webhook puts parsed JSON at $input.item.json (root), not under .body
const body = ($input.item.json && $input.item.json.body != null) ? $input.item.json.body : ($input.item.json || {});
const schema = body.schema || [];
const recordCount = body.recordCount || 100;
const exportFormat = body.exportFormat || 'csv';
const sampleData = body.sampleData || null;
const fieldPatterns = body.fieldPatterns || {}; // CRITICAL: From AI Mode

console.log('📥 Simple Generator Input:');
console.log('Schema fields:', schema.map(f => f.name).join(', '));
console.log('Record count:', recordCount);
console.log('Field patterns received:', Object.keys(fieldPatterns).join(', ') || 'None');

// Validate inputs
if (!schema || schema.length === 0) {
  return [{
    json: {
      success: false,
      error: 'Schema is required and must contain at least one field'
    }
  }];
}

if (recordCount < 1 || recordCount > 10000) {
  return [{
    json: {
      success: false,
      error: 'Record count must be between 1 and 10,000'
    }
  }];
}

// ============================================
// STEP 1: Extract or use provided patterns (100% GENERIC)
// ============================================
let extractedPatterns = {};

// Use patterns from AI Mode if provided
if (fieldPatterns && Object.keys(fieldPatterns).length > 0) {
  extractedPatterns = fieldPatterns;
  console.log('✅ Using patterns from AI Mode:', Object.keys(extractedPatterns));
  Object.keys(extractedPatterns).forEach(key => {
    console.log(`  - ${key}: ${extractedPatterns[key].length} values`);
  });
}
// Extract from sampleData if provided (Schema Builder mode)
else if (sampleData && Array.isArray(sampleData) && sampleData.length > 0) {
  console.log('✅ Extracting patterns from sampleData...');

  sampleData.forEach(record => {
    Object.keys(record).forEach(fieldName => {
      const value = record[fieldName];

      if (value === null || value === undefined || value === '') return;

      if (!extractedPatterns[fieldName]) {
        extractedPatterns[fieldName] = [];
      }

      if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
        const stringValue = String(value).trim();
        if (stringValue && !extractedPatterns[fieldName].includes(stringValue)) {
          extractedPatterns[fieldName].push(stringValue);
        }
      }
    });
  });

  console.log('✅ Patterns extracted:', Object.keys(extractedPatterns));
} else {
  console.log('ℹ️ No patterns available, using type-based generators only');
}

// ============================================
// STEP 2: Pattern matcher (exact, case-insensitive, partial)
// ============================================
function getPatternValue(fieldName) {
  if (!extractedPatterns || Object.keys(extractedPatterns).length === 0) {
    return null;
  }

  const fieldNameLower = fieldName.toLowerCase();

  // Exact match
  if (extractedPatterns[fieldName] && extractedPatterns[fieldName].length > 0) {
    return extractedPatterns[fieldName][Math.floor(Math.random() * extractedPatterns[fieldName].length)];
  }

  // Case-insensitive match
  for (const patternFieldName in extractedPatterns) {
    if (patternFieldName.toLowerCase() === fieldNameLower && extractedPatterns[patternFieldName].length > 0) {
      return extractedPatterns[patternFieldName][Math.floor(Math.random() * extractedPatterns[patternFieldName].length)];
    }
  }

  // Partial match (only if pattern is significant substring)
  for (const patternFieldName in extractedPatterns) {
    const patternFieldNameLower = patternFieldName.toLowerCase();
    if (fieldNameLower.includes(patternFieldNameLower) && 
        patternFieldNameLower.length > 3 && 
        extractedPatterns[patternFieldName].length > 0) {
      return extractedPatterns[patternFieldName][Math.floor(Math.random() * extractedPatterns[patternFieldName].length)];
    }
  }

  return null;
}

// ============================================
// STEP 3: Type-based generators (fallback only)
// ============================================
function generateByType(fieldType) {
  const typeLower = (fieldType || 'string').toLowerCase();

  if (typeLower === 'int' || typeLower === 'integer') {
    return Math.floor(Math.random() * 10000) + 1;
  }

  if (typeLower === 'decimal' || typeLower === 'float' || typeLower === 'double' || typeLower === 'number') {
    return parseFloat((Math.random() * 1000).toFixed(2));
  }

  if (typeLower === 'boolean' || typeLower === 'bool') {
    return Math.random() > 0.5;
  }

  if (typeLower === 'date') {
    const start = new Date(2020, 0, 1);
    const end = new Date();
    const date = new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime()));
    return date.toISOString().split('T')[0];
  }

  if (typeLower === 'datetime' || typeLower === 'timestamp') {
    const start = new Date(2020, 0, 1);
    const end = new Date();
    return new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime())).toISOString();
  }

  if (typeLower === 'uuid' || typeLower === 'guid') {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
      const r = Math.random() * 16 | 0;
      const v = c === 'x' ? r : (r & 0x3 | 0x8);
      return v.toString(16);
    });
  }

  if (typeLower === 'email') {
    const num = Math.floor(Math.random() * 10000);
    return `user${num}@example.com`;
  }

  if (typeLower === 'url' || typeLower === 'website') {
    return `https://example${Math.floor(Math.random() * 1000)}.com`;
  }

  if (typeLower === 'phone' || typeLower === 'telephone') {
    const area = Math.floor(Math.random() * 900) + 100;
    const prefix = Math.floor(Math.random() * 900) + 100;
    const line = Math.floor(Math.random() * 9000) + 1000;
    return `(${area}) ${prefix}-${line}`;
  }

  // Default: generic string
  return `sample_${typeLower}_value`;
}

// ============================================
// STEP 4: FULLY GENERIC value generator
// ============================================
function generateValue(fieldName, fieldType) {
  // PRIORITY 1: Pattern matching (works for ANY field)
  const patternValue = getPatternValue(fieldName);
  if (patternValue !== null) {
    return patternValue;
  }

  // PRIORITY 2: Type-based fallback
  return generateByType(fieldType);
}

// ============================================
// STEP 5: Generate full dataset
// ============================================
const data = [];
console.log(`🔄 Generating ${recordCount} records...`);

for (let i = 0; i < recordCount; i++) {
  const record = {};

  schema.forEach(field => {
    const blankPercentage = field.blankPercentage || 0;
    const shouldBeBlank = Math.random() * 100 < blankPercentage;

    if (shouldBeBlank) {
      record[field.name] = null;
    } else {
      record[field.name] = generateValue(field.name, field.type);
    }
  });

  data.push(record);
}

console.log(`✅ Generated ${data.length} records successfully`);
console.log(`📊 Sample record:`, JSON.stringify(data[0]));

// Return result
return [{
  json: {
    success: true,
    data: data,
    recordCount: data.length,
    exportFormat: exportFormat,
    patternsUsed: Object.keys(extractedPatterns).length
  }
}];
